INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('government','government',0,'government','The Government','정부','On paper the ministries and elections of the Republic of Korea; in practice rank follows the number of stationmasters a person commands: stationmaster, division chief, bureau chief, commissioner (appointed by the President), President','서류상으로는 대한민국의 부처와 선거를 유지하나 실제 계급은 거느린 역장 수로 정한다: 역장, 본부장, 국장, 청장(대통령 임명), 대통령','14 districts, 153 stations (provisional)','14개 구, 153개 역(잠정)','The surviving administration north of the Han River after the Great Blackout; only people written in its register count as citizens. It has officers, heavy weapons, tanks, and original seed stock, but no medical technicians','대정전 이후 한강 이북에 남은 행정으로, 명부에 오른 사람만 국민으로 인정한다. 장교층·중화기·전차·원종 씨앗을 쥐었으나 의료기술자가 없다','President Kim Yeongyu (for life; appoints commissioners)','대통령 김연규 (종신, 청장 임명)','Gwanghwamun','광화문','Gangbuk Centered on Cheongwadae','청와대를 중심으로 한 강북');
INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('free-city','free-city',1,'free-city','Free City','자유도시','Cities joined only by the Board, holding that refusing to be ruled is freedom: stationmaster, division chief, guild master, director (appointed by the Board), Chair of the Board','지배를 거부하는 것을 자유로 여기며 이사회 하나로만 이어진 도시들: 역장, 본부장, 조합장, 이사(이사회 임명), 이사회장','7 districts, 77 stations (provisional)','7개 구, 77개 역(잠정)','Cities of doctors, technicians, and farming south-west of the Han River after the Great Blackout; almost all of Seouls doctors and neural-link surgeons live here','대정전 이후 한강 남서쪽 의사와 기술자와 농사의 도시들로, 서울의 의사와 신경 연결 시술자가 거의 모두 여기에 있다','Chair of the Board I Ilseop (by rank one director; the I family holds the chair by inheritance)','이사회장 이일섭 (계급상 이사, 이씨 가문이 대대로 맡음)','None (the Chairs family is based in Gwanak)','없음 (이사회장 가문의 근거지는 관악)','Western Area South of the Han River','한강 이남 서부');
INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('arc','arc',2,'arc','Arc','아크','A faith with the Hierophant at its peak: stationmaster, division chief, bishop, cardinal (ordained by the Hierophant), Hierophant','교주를 정점에 둔 신앙 세력: 역장, 본부장, 주교, 추기경(교주 서품), 교주','4 districts, 77 stations (provisional)','4개 구, 77개 역(잠정)','Split off from the Free City; around 2122 the Gangnam shelters were bound together under the name Arc. It holds a monopoly on ancient data-center software but has no factories, heavy weapons, or hospitals','자유도시에서 갈라져 나왔고, 2122년 무렵 강남 대피소들이 아크라는 이름으로 묶였다. 고대 데이터센터 소프트웨어를 독점하나 공장·중화기·병원이 없다','Hierophant Go Ye-jin (Messiah)','교주 고예진 (메시아)','Samseong','삼성','Gangnam Area South of the Han River','한강 이남 강남지역');
